import 'dart:io';
import 'package:atlassian_apis/jira_platform.dart';

void main() async {
  var user = Platform.environment['ATLASSIAN_USER']!;
  var token = Platform.environment['ATLASSIAN_API_TOKEN']!;
  var client = ApiClient.basicAuthentication(
      Uri.https('<your-account>.atlassian.net', ''),
      user: user,
      apiToken: token);
  var jira = JiraPlatformApi(client);
  var projects = await jira.projects.searchProjects();
  print(projects);
  client.close();
}
